mapper.select:
SELECT ID, CODE, NAME, STATUS, SORT_NO FROM ( SELECT T.ID, T.CODE, T.NAME, T.STATUS, T.SORT_NO, ROW_NUMBER() OVER ( ORDER BY
${orderBy} T.SORT_NO ASC, T.ID ASC
) RN FROM E_PRINT_TEMPLATE_TYPE T WHERE 1 = 1
AND ( LOWER(T.CODE) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(T.NAME) LIKE '%' || LOWER(#{keyword}) || '%' )
AND T.STATUS = #{status}
) WHERE RN > #{rowStart} AND RN <= #{rowEnd} ORDER BY RN

SELECT COUNT(1) FROM E_PRINT_TEMPLATE_TYPE T WHERE 1 = 1
AND ( LOWER(T.CODE) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(T.NAME) LIKE '%' || LOWER(#{keyword}) || '%' )
AND T.STATUS = #{status}

mapper.update:
UPDATE E_PRINT_TEMPLATE_TYPE
SET STATUS = #{status}
WHERE ID = #{id}

UPDATE E_PRINT_TEMPLATE_TYPE
SET STATUS = #{status}
WHERE ID IN

    #{id}

mapper.delete:
DELETE FROM E_PRINT_TEMPLATE_TYPE
WHERE ID IN

    #{id}

mapper.select:
SELECT COUNT(1)
FROM E_PRINT_TEMPLATE T
WHERE T.TEMPLATE_TYPE_ID = #{id}
